import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"技术","description":"先会说话，再会查资料，再会让模型动手。从 LLM / 提示 / 上下文拆下去。","frontmatter":{"title":"技术","description":"先会说话，再会查资料，再会让模型动手。从 LLM / 提示 / 上下文拆下去。","domain":"tech","tags":["tech"],"listed":false,"outline":[2,3],"pageClass":"catalog-page"},"headers":[],"relativePath":"zh/tech/index.md","filePath":"zh/tech/index.md","lastUpdated":1788250975000}'),l={name:"zh/tech/index.md"};function i(h,a,s,o,p,d){return n(),e("div",null,[...a[0]||(a[0]=[r(`<h1 id="技术" tabindex="-1">技术 <a class="header-anchor" href="#技术" aria-label="Permalink to &quot;技术&quot;">​</a></h1><p><strong>结论先讲</strong>：前端工程师用 AI，不是先训模型。顺序是——</p><ol><li>会跟模型说话（提示 + 上下文）</li><li>会把模型接到自己的应用（API / 流式 UI）</li><li>会让它查你的资料（RAG）</li><li>会让它动手（工具 / Agent / Skill / MCP）</li><li>最后才谈评估、成本和要不要微调</li></ol><p>这和 <a href="/zh/products/cursor/">Cursor 学习导航</a> 同一套：先全景，再按任务拆。左侧侧栏按这个顺序排。</p><p><strong>不是</strong>：某个产品的逐步点击（去 <a href="/zh/products/">产品</a>），也不是 Transformer 内部推导（去 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>）。</p><h2 id="一张图-你现在卡在哪" tabindex="-1">一张图：你现在卡在哪 <a class="header-anchor" href="#一张图-你现在卡在哪" aria-label="Permalink to &quot;一张图：你现在卡在哪&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要解决什么？</span></span>
<span class="line"><span>├── 模型到底吃什么、记住什么          → 基础（LLM / 上下文 / Embeddings）</span></span>
<span class="line"><span>├── 提示写不清楚、输出不稳            → Prompt</span></span>
<span class="line"><span>├── 要在 React / Vue 里接上模型        → 集成（API / SDK / 流式）</span></span>
<span class="line"><span>├── 回答必须基于我们自己的文档        → RAG</span></span>
<span class="line"><span>├── 要它改文件、调工具、走多步        → Agent / Skills / MCP</span></span>
<span class="line"><span>└── 要上线、要测、要控账单            → 工程与评估</span></span></code></pre></div><h2 id="_1-基础-模型看见什么" tabindex="-1">1. 基础：模型看见什么 <a class="header-anchor" href="#_1-基础-模型看见什么" aria-label="Permalink to &quot;1. 基础：模型看见什么&quot;">​</a></h2><p>先建立三块词汇，后面所有页都用它们。</p><table tabindex="0"><thead><tr><th>概念</th><th>你当什么用</th><th>页</th></tr></thead><tbody><tr><td>LLM</td><td>一个吃文本、吐文本的 API</td><td><a href="/zh/tech/fundamentals/LLM.html">LLM 基础</a></td></tr><tr><td>上下文窗口</td><td>这一轮它能看见的字数上限</td><td><a href="/zh/tech/fundamentals/context.html">上下文窗口</a></td></tr><tr><td>Embeddings</td><td>把句子变成可比较的向量</td><td><a href="/zh/tech/fundamentals/embeddings.html">Embeddings</a></td></tr><tr><td>上下文工程</td><td>往窗口里塞什么、丢掉什么</td><td><a href="/zh/tech/fundamentals/context-engineering.html">上下文工程</a></td></tr></tbody></table><p>机制（注意力、训练、记忆）见 Learn LLM；本栏只建立概念，然后接到工程和工具。</p><h2 id="_2-怎么写-prompt" tabindex="-1">2. 怎么写：Prompt <a class="header-anchor" href="#_2-怎么写-prompt" aria-label="Permalink to &quot;2. 怎么写：Prompt&quot;">​</a></h2><p>会用工具之后，质量差几乎都是提示和上下文没写清。这一栏是一条路径，不是合集。</p><ol><li><a href="/zh/tech/prompt/">地图 · 怎么写</a>：20 分钟主课（任务 / 约束 / 输出 / 示例）</li><li><a href="/tech/prompt/claude-prompt-best-practices.html">说清楚</a> → <a href="/zh/tech/prompt/json-prompt-best-practices.html">稳住结构</a> → <a href="/zh/tech/prompt/agents-doc.html">写给仓库</a></li><li>换了新模型再读 <a href="/zh/tech/prompt/official-guide-2026.html">换模型时改什么</a>；System Prompts 只当附录查阅</li></ol><h2 id="_3-怎么接到产品-集成" tabindex="-1">3. 怎么接到产品：集成 <a class="header-anchor" href="#_3-怎么接到产品-集成" aria-label="Permalink to &quot;3. 怎么接到产品：集成&quot;">​</a></h2><p>有手感了，再把模型嵌进自己的应用。</p><ul><li><a href="/zh/integration/apis/">API 对比</a> → OpenAI / Anthropic / 流式</li><li><a href="/zh/integration/frameworks/">框架</a>：Vercel AI SDK、LangChain.js、Next.js</li><li><a href="/zh/integration/protocols/tool-calling.html">工具调用</a></li><li>前端本地跑小模型：<a href="/zh/integration/frontend-ml/transformersjs.html">Transformers.js</a></li></ul><h2 id="_4-怎么查资料-rag" tabindex="-1">4. 怎么查资料：RAG <a class="header-anchor" href="#_4-怎么查资料-rag" aria-label="Permalink to &quot;4. 怎么查资料：RAG&quot;">​</a></h2><p>文档、工单、代码库不能靠模型「背下来」。先检索，再生成。</p><ul><li><a href="/zh/tech/patterns/RAG.html">RAG</a></li><li>语义搜索实践：<a href="/zh/tech/ai-application/building-semantic-search.html">构建语义搜索</a></li></ul><p>微调（SFT / RLHF）比 RAG 贵一个数量级，默认别上。见 <a href="/zh/tech/training/SFT.html">SFT</a>。</p><h2 id="_5-怎么让它做事-agent" tabindex="-1">5. 怎么让它做事：Agent <a class="header-anchor" href="#_5-怎么让它做事-agent" aria-label="Permalink to &quot;5. 怎么让它做事：Agent&quot;">​</a></h2><p>多步、要调工具、要改仓库时，才需要 Agent。先读选用，再读模式。</p><ul><li><a href="/zh/tech/patterns/agent/">Agent 概览</a></li><li><a href="/zh/tech/agent/agent-design-patterns.html">设计模式</a></li><li><a href="/zh/tech/skills/">Skills</a> · <a href="/zh/tech/mcp/">MCP</a> · <a href="/zh/integration/protocols/tool-calling.html">工具调用</a></li></ul><h2 id="_6-怎么验和控" tabindex="-1">6. 怎么验和控 <a class="header-anchor" href="#_6-怎么验和控" aria-label="Permalink to &quot;6. 怎么验和控&quot;">​</a></h2><p>功能能跑之后：测、看、限流、算钱。</p><ul><li><a href="/zh/tech/engineering/testing.html">测试</a> · <a href="/zh/tech/engineering/evals.html">评估</a></li><li><a href="/zh/tech/engineering/observability.html">可观测性</a> · <a href="/zh/tech/engineering/security.html">安全</a> · <a href="/zh/tech/engineering/cost-optimization.html">成本</a></li></ul><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><p>路径 1 的人：基础 → Prompt。<br> 路径 2 的人：集成 → RAG。<br> 路径 3 的人：工程与评估；Agent 按需。</p><p>不要从侧栏最底下的「更多」倒着读。</p>`,30)])])}const b=t(l,[["render",i]]);export{u as __pageData,b as default};
